// tutor-api.js.
import { createContext, useContext } from "react";

/** @typedef {{ ask(question: string, signal?: AbortSignal): Promise<{ answer: string }> }} TutorApi */
const TutorApiContext = createContext(/** @type {TutorApi | null} */ (null));

export function TutorApiProvider({ api, children }) {
  return <TutorApiContext.Provider value={api}>{children}</TutorApiContext.Provider>;
}

export function useTutorApi() {
  const api = useContext(TutorApiContext);
  if (!api) throw new Error("useTutorApi must be used inside TutorApiProvider");
  return api;
}

// main.jsx: created once, outside render.
const realApi = createHttpTutorApi(new URL("/api/tutor", location.origin));
root.render(<TutorApiProvider api={realApi}><App /></TutorApiProvider>);

// Test: a fake with the same interface.
const fake = { ask: vi.fn().mockResolvedValue({ answer: "Use a loop." }) };
render(<TutorApiProvider api={fake}><TutorChat /></TutorApiProvider>);
```

| Put in a service context | Keep as props or state |
|---|---|
| API clients, analytics, feature policy. | data that changes often. |
| created once, stable. | per-component values. |
| small interface. | anything a direct parent can pass. |

